 84→function readWorkbook(fileNameFragment: string) {
 85→  const fullPath = findReferenceFile(fileNameFragment, ".xlsx");
 86→  return XLSX.readFile(fullPath, { cellDates: true });
 87→}
 88→
 89→function findReferenceFile(fragment: string, extension: string) {
 90→  const entry = fs
 91→    .readdirSync(REFERENCE_DIR)
 92→    .find(
 93→      (name) =>
 94→        name.endsWith(extension) &&
 95→        !name.startsWith("~$") &&
 96→        name.includes(fragment),
 97→    );
 98→
 99→  if (!entry) {
100→    throw new Error(`Reference file not found for fragment: ${fragment}`);
101→  }
102→
103→  return path.join(REFERENCE_DIR, entry);
104→}
