106→function normalizeDepartmentKey(value: CellValue) {
107→  return String(value ?? "")
108→    .trim()
109→    .replace(/\s+/g, "")
110→    .replace(/[·.,()\-_/]/g, "")
111→    .replace(/학부\/대학/g, "")
112→    .toLowerCase();
113→}
114→
115→function cleanText(value: CellValue) {
116→  if (value === null || value === undefined) {
117→    return null;
118→  }
119→
120→  const text = String(value).replace(/\r/g, "").replace(/\n/g, " ").trim();
121→  return text.length ? text : null;
122→}
123→
124→function toNumber(value: CellValue) {
125→  if (value === null || value === undefined || value === "" || value === "*") {
126→    return null;
127→  }
128→
129→  const numeric = Number(String(value).replace(/[^\d.+-]/g, ""));
130→  return Number.isNaN(numeric) ? null : numeric;
131→}
132→
133→function combineHeaders(primary: CellValue[], secondary: CellValue[]) {
134→  const results: string[] = [];
135→  let lastPrimary = "";
136→
137→  for (let index = 0; index < Math.max(primary.length, secondary.length); index += 1) {
138→    const group = cleanText(primary[index]) ?? lastPrimary;
139→    const label = cleanText(secondary[index]);
140→    if (group) {
141→      lastPrimary = group;
142→    }
143→
144→    results.push(label ? `${lastPrimary} ${label}`.trim() : lastPrimary.trim());
145→  }
146→
147→  return results;
148→}
