160→function inferDepartmentName(candidate: CellValue, fallbackCandidate?: CellValue) {
161→  const values = [candidate, fallbackCandidate]
162→    .map(cleanText)
163→    .filter((value): value is string => Boolean(value) && value !== "X");
164→
