210→function buildDepartmentResolver() {
211→  const departments = new Map<
212→    string,
213→    {
214→      deptCode: string;
215→      deptName: string;
216→    }
217→  >();
218→
219→  const baseWorkbook = readWorkbook("기초데이터");
220→  const baseSheet = baseWorkbook.Sheets[baseWorkbook.SheetNames[0]];
221→  const rows = XLSX.utils.sheet_to_json<CellValue[]>(baseSheet, {
222→    header: 1,
223→    raw: false,
224→    defval: null,
225→  });
226→
227→  const headers = combineHeaders(rows[4] ?? [], rows[5] ?? []);
228→  const dataRows = rows.slice(6).filter((row) => cleanText(row[2]));
229→  const usedDeptCodes = new Set<string>();
230→
231→  const insertDepartment = getDb().prepare(`
232→    INSERT INTO departments (
233→      dept_code,
234→      dept_name,
235→      normalized_dept_name,
236→      college,
237→      category,
238→      division_name,
239→      sort_order,
240→      current_faculty_general,
241→      current_faculty_dedicated,
242→      current_faculty_foreign,
243→      current_faculty_total,
244→      faculty_securing_rate,
245→      department_stats_json
246→    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
247→  `);
248→
249→  for (const row of dataRows) {
250→    const deptName = cleanText(row[2]);
251→    if (!deptName) {
252→      continue;
253→    }
254→
255→    const normalized = normalizeDepartmentKey(deptName);
256→    const rawDeptCode = cleanText(row[3]) ?? normalized;
257→    const deptCode = usedDeptCodes.has(rawDeptCode)
258→      ? `${rawDeptCode}_${normalized}`
259→      : rawDeptCode;
260→    const rowObject = rowToObject(headers, row);
261→    usedDeptCodes.add(deptCode);
262→
263→    departments.set(normalized, { deptCode, deptName });
264→    departments.set(normalizeDepartmentKey(EXPLICIT_DEPARTMENT_ALIASES[deptName] ?? deptName), {
265→      deptCode,
266→      deptName,
267→    });
268→
269→    insertDepartment.run(
270→      deptCode,
271→      deptName,
272→      normalized,
273→      cleanText(row[0]),
274→      cleanText(row[1]),
275→      cleanText(row[2]),
276→      toNumber(row[3]),
277→      toNumber(row[16]) ?? 0,
278→      toNumber(row[17]) ?? 0,
279→      toNumber(row[18]) ?? 0,
280→      toNumber(row[19]) ?? 0,
281→      toNumber(row[21]),
282→      JSON.stringify(rowObject),
283→    );
284→  }
285→
286→  return (candidate: CellValue, fallbackCandidate?: CellValue) => {
287→    const inferred = inferDepartmentName(candidate, fallbackCandidate);
288→    if (!inferred) {
289→      return null;
290→    }
291→
292→    const alias = EXPLICIT_DEPARTMENT_ALIASES[inferred] ?? inferred;
293→    const normalized = normalizeDepartmentKey(alias);
294→    return departments.get(normalized) ?? null;
295→  };
296→}
