654→    FROM recruitment_requests
655→    WHERE dept_code = ? AND is_active = 1
656→    ORDER BY CASE WHEN hiring_type = '상시' THEN 0 ELSE 1 END, CAST(priority AS INTEGER) ASC, id ASC
657→    LIMIT 1
