702→```typescript
703→// lib/permissions.ts
704→import { getDb } from "./db";
705→
706→export function checkPermission(
707→  role: string,
708→  resource: string,
709→  action: string
710→): boolean {
711→  const db = getDb();
712→
713→  // 먼저 와일드카드 '*' 체크
714→  const wildcard = db
715→    .prepare(
716→      "SELECT allowed FROM permissions WHERE role = ? AND resource = '*' AND action = ? LIMIT 1"
717→    )
718→    .get(role, action) as { allowed: number } | undefined;
719→
720→  if (wildcard) return wildcard.allowed === 1;
721→
722→  // 정확한 resource 체크
723→  const exact = db
724→    .prepare(
725→      "SELECT allowed FROM permissions WHERE role = ? AND resource = ? AND action = ? LIMIT 1"
726→    )
727→    .get(role, resource, action) as { allowed: number } | undefined;
728→
729→  if (exact) return exact.allowed === 1;
730→
731→  // 권한 레코드가 없으면 거부
732→  return false;
733→}
734→
735→export function getPermissionsForRole(role: string): {
736→  resource: string;
737→  action: string;
738→  allowed: boolean;
739→}[] {
740→  const db = getDb();
741→  const rows = db
742→    .prepare("SELECT resource, action, allowed FROM permissions WHERE role = ?")
743→    .all(role) as { resource: string; action: string; allowed: number }[];
744→  return rows.map((r) => ({
745→    resource: r.resource,
746→    action: r.action,
747→    allowed: r.allowed === 1,
748→  }));
749→}
750→
751→export function updatePermissions(
752→  role: string,
753→  changes: { resource: string; action: string; allowed: boolean }[]
754→): void {
755→  const db = getDb();
756→  const upsert = db.prepare(`
757→    INSERT INTO permissions (role, resource, action, allowed)
758→    VALUES (?, ?, ?, ?)
759→    ON CONFLICT(role, resource, action)
760→    DO UPDATE SET allowed = excluded.allowed, updated_at = CURRENT_TIMESTAMP
761→  `);
762→  const tx = db.transaction(() => {
763→    for (const c of changes) {
764→      upsert.run(role, c.resource, c.action, c.allowed ? 1 : 0);
765→    }
766→  });
767→  tx();
768→}
769→
770→export function getAllRoles(): string[] {
771→  const db = getDb();
772→  const rows = db
773→    .prepare("SELECT DISTINCT role FROM permissions ORDER BY role")
774→    .all() as { role: string }[];
775→  return rows.map((r) => r.role);
776→}
777→
778→export function createRole(role: string): void {
779→  const db = getDb();
780→  const RESOURCES = [
781→    "dashboard.summary", "dashboard.allocation", "dashboard.progress",
782→    "candidates", "procedures", "actions",
783→    "admin.data-sheet", "admin.workflow",
784→    "system.permissions", "system.users",
785→    "etc",
786→  ];
787→  const ACTIONS = ["view", "edit", "delete", "export", "import"];
788→  const insert = db.prepare(
789→    "INSERT OR IGNORE INTO permissions (role, resource, action, allowed) VALUES (?, ?, ?, 0)"
790→  );
791→  const tx = db.transaction(() => {
792→    for (const resource of RESOURCES) {
793→      for (const action of ACTIONS) {
794→        insert.run(role, resource, action);
795→      }
796→    }
797→  });
798→  tx();
799→}
800→
801→export function deleteRole(role: string): { success: boolean; error?: string } {
802→  const db = getDb();
803→  const userCount = db
804→    .prepare("SELECT COUNT(*) as count FROM users WHERE role = ?")
805→    .get(role) as { count: number };
806→  if (userCount.count > 0) {
807→    return { success: false, error: `${userCount.count}명의 사용자가 이 역할을 사용 중입니다.` };
808→  }
809→  db.prepare("DELETE FROM permissions WHERE role = ?").run(role);
810→  return { success: true };
811→}
812→
813→export function getViewableResources(role: string): string[] {
814→  const db = getDb();
815→
816→  // 와일드카드 체크
817→  const wildcard = db
818→    .prepare("SELECT allowed FROM permissions WHERE role = ? AND resource = '*' AND action = 'view'")
819→    .get(role) as { allowed: number } | undefined;
820→
821→  if (wildcard?.allowed === 1) {
822→    const RESOURCES = [
823→      "dashboard.summary", "dashboard.allocation", "dashboard.progress",
824→      "candidates", "procedures", "actions",
825→      "admin.data-sheet", "admin.workflow",
826→      "system.permissions", "system.users",
827→    ];
828→    return RESOURCES;
829→  }
830→
831→  const rows = db
832→    .prepare("SELECT resource FROM permissions WHERE role = ? AND action = 'view' AND allowed = 1")
833→    .all(role) as { resource: string }[];
834→  return rows.map((r) => r.resource);
835→}
