 893→
 894→export async function GET() {
 895→  const user = await requireUser();
 896→  if (!checkPermission(user.role, "system.permissions", "view")) {
 897→    return NextResponse.json({ error: "FORBIDDEN" }, { status: 403 });
 898→  }
 899→
 900→  const roles = getAllRoles();
 901→  const result: Record<string, { resource: string; action: string; allowed: boolean }[]> = {};
 902→  for (const role of roles) {
 903→    result[role] = getPermissionsForRole(role);
 904→  }
 905→  return NextResponse.json({ roles, permissions: result });
 906→}
 907→
 908→export async function PATCH(req: NextRequest) {
 909→  const user = await requireUser();
 910→  if (!checkPermission(user.role, "system.permissions", "edit")) {
 911→    return NextResponse.json({ error: "FORBIDDEN" }, { status: 403 });
 912→  }
 913→
 914→  const body = await req.json();
 915→  const { role, changes } = body as {
 916→    role: string;
 917→    changes: { resource: string; action: string; allowed: boolean }[];
 918→  };
 919→
 920→  updatePermissions(role, changes);
 921→  return NextResponse.json({ success: true });
 922→}
