 6→
 7→type WorkflowFormProps = {
 8→  detail: WorkflowRequestDetail;
 9→};
10→
11→export function WorkflowForm({ detail }: WorkflowFormProps) {
12→  const router = useRouter();
13→  const [values, setValues] = useState<Record<string, string>>({});
14→  const [error, setError] = useState("");
15→  const [saving, setSaving] = useState(false);
16→
17→  if (!detail.currentForm) {
18→    return <p className="text-sm text-[#9fb4a5]">현재 단계에는 제출해야 할 별도 입력 폼이 없습니다.</p>;
19→  }
20→
21→  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
22→    event.preventDefault();
23→    setSaving(true);
24→    setError("");
25→
26→    try {
27→      const response = await fetch(`/api/recruitment-requests/${detail.request.id}/submit`, {
28→        method: "POST",
29→        headers: { "Content-Type": "application/json" },
30→        body: JSON.stringify({ values }),
31→      });
32→
33→      if (!response.ok) {
34→        const data = (await response.json()) as { message?: string };
35→        throw new Error(data.message ?? "제출에 실패했습니다.");
36→      }
37→
38→      router.push(`/procedures/${detail.request.id}`);
39→      router.refresh();
40→    } catch (caught) {
41→      setError(caught instanceof Error ? caught.message : "제출에 실패했습니다.");
42→    } finally {
43→      setSaving(false);
44→    }
45→  }
46→
47→  return (
48→    <form onSubmit={handleSubmit} className="space-y-5">
49→      {detail.currentForm.fields.map((field) => (
50→        <label key={field.name} className="block space-y-2">
51→          <span className="text-sm font-medium text-[#dbe8df]">
52→            {field.label}
53→            {field.required ? " *" : ""}
54→          </span>
55→          {field.type === "textarea" ? (
56→            <textarea
57→              rows={5}
58→              value={values[field.name] ?? ""}
59→              onChange={(event) => setValues((current) => ({ ...current, [field.name]: event.target.value }))}
60→              placeholder={field.placeholder}
61→              className="w-full rounded-[1.25rem] border border-[#355845] bg-[#173328] px-4 py-3 text-sm leading-6 text-white outline-none focus:border-[#7fb18f]"
62→            />
63→          ) : (
64→            <input
65→              type={field.type}
66→              value={values[field.name] ?? ""}
67→              onChange={(event) => setValues((current) => ({ ...current, [field.name]: event.target.value }))}
68→              placeholder={field.placeholder}
69→              className="w-full rounded-2xl border border-[#355845] bg-[#173328] px-4 py-3 text-sm text-white outline-none focus:border-[#7fb18f]"
70→            />
71→          )}
72→          {field.helpText ? <span className="text-xs text-[#9fb4a5]">{field.helpText}</span> : null}
73→        </label>
74→      ))}
75→
76→      {error ? <p className="rounded-2xl bg-[#4d241f] px-4 py-3 text-sm text-[#ffd8d0]">{error}</p> : null}
77→
78→      <button
79→        type="submit"
80→        disabled={saving}
81→        className="rounded-full bg-[#1f5b43] px-5 py-3 text-sm font-semibold text-white transition-colors hover:bg-[#276d50] disabled:opacity-70"
82→      >
83→        {saving ? "제출 중..." : "제출 후 다음 단계로 이동"}
84→      </button>
85→    </form>
86→  );
87→}
