import { NextRequest, NextResponse } from "next/server";
import { requireUser } from "@/lib/auth";
import {
  checkPermission,
  getPermissionsForRole,
  updatePermissions,
  getAllRoles,
} from "@/lib/permissions";

export async function GET() {
  const user = await requireUser();
  if (!checkPermission(user.role, "system.permissions", "view")) {
    return NextResponse.json({ error: "FORBIDDEN" }, { status: 403 });
  }

  const roles = getAllRoles();
  const result: Record<string, { resource: string; action: string; allowed: boolean }[]> = {};
  for (const role of roles) {
    result[role] = getPermissionsForRole(role);
  }
  return NextResponse.json({ roles, permissions: result });
}

export async function PATCH(req: NextRequest) {
  const user = await requireUser();
  if (!checkPermission(user.role, "system.permissions", "edit")) {
    return NextResponse.json({ error: "FORBIDDEN" }, { status: 403 });
  }

  const body = await req.json();
  const { role, changes } = body as {
    role: string;
    changes: { resource: string; action: string; allowed: boolean }[];
  };

  updatePermissions(role, changes);
  return NextResponse.json({ success: true });
}

import { NextRequest, NextResponse } from "next/server";
import { requireUser } from "@/lib/auth";
import { checkPermission, createRole } from "@/lib/permissions";

export async function POST(req: NextRequest) {
  const user = await requireUser();
  if (!checkPermission(user.role, "system.permissions", "edit")) {
    return NextResponse.json({ error: "FORBIDDEN" }, { status: 403 });
  }

  const { role } = (await req.json()) as { role: string };
  if (!role || role.trim().length === 0) {
    return NextResponse.json({ error: "역할 이름을 입력해주세요." }, { status: 400 });
  }

  createRole(role.trim().toUpperCase());
  return NextResponse.json({ success: true });
}

import { NextRequest, NextResponse } from "next/server";
import { requireUser } from "@/lib/auth";
import { checkPermission, deleteRole } from "@/lib/permissions";
import { DEFAULT_ROLES } from "@/lib/types";

export async function DELETE(
  _req: NextRequest,
  { params }: { params: Promise<{ role: string }> }
) {
  const user = await requireUser();
  if (!checkPermission(user.role, "system.permissions", "edit")) {
    return NextResponse.json({ error: "FORBIDDEN" }, { status: 403 });
  }

  const { role } = await params;
  if ((DEFAULT_ROLES as readonly string[]).includes(role)) {
    return NextResponse.json(
      { error: "기본 역할은 삭제할 수 없습니다." },
      { status: 400 }
    );
  }

  const result = deleteRole(role);
  if (!result.success) {
    return NextResponse.json({ error: result.error }, { status: 400 });
  }
  return NextResponse.json({ success: true });
}

"use client";

import { useState } from "react";

type PermissionEntry = {
  resource: string;
  action: string;
  allowed: boolean;
};

type Props = {
  roles: string[];
  permissions: Record<string, PermissionEntry[]>;
};

const RESOURCE_GROUPS: { title: string; resources: { key: string; label: string }[] }[] = [
  {
    title: "대시보드",
    resources: [
      { key: "dashboard.summary", label: "현황 요약" },
      { key: "dashboard.allocation", label: "TO 배분표" },
      { key: "dashboard.progress", label: "채용 진행현황" },
    ],
  },
  {
    title: "후보자",
    resources: [{ key: "candidates", label: "후보자 관리" }],
  },
  {
    title: "채용 절차",
    resources: [
      { key: "procedures", label: "채용 절차 상세" },
      { key: "actions", label: "단계별 제출" },
    ],
  },
  {
    title: "관리",
    resources: [
      { key: "admin.data-sheet", label: "데이터 관리 (DB 시트)" },
      { key: "admin.workflow", label: "워크플로우 매트릭스" },
    ],
  },
  {
    title: "시스템",
    resources: [
      { key: "system.permissions", label: "권한 관리" },
      { key: "system.users", label: "사용자 관리" },
    ],
  },
  {
    title: "기타",
    resources: [{ key: "etc", label: "기타" }],
  },
];

const ACTIONS = [
  { key: "view", label: "보기" },
  { key: "edit", label: "편집" },
  { key: "delete", label: "삭제" },
  { key: "export", label: "내보내기" },
  { key: "import", label: "가져오기" },
];

export default function PermissionMatrix({ roles, permissions }: Props) {
  const [activeRole, setActiveRole] = useState(roles[0] || "ADMIN");
  const [localPerms, setLocalPerms] = useState(permissions);
  const [saving, setSaving] = useState(false);
  const [newRole, setNewRole] = useState("");
  const [message, setMessage] = useState("");

  function isAllowed(role: string, resource: string, action: string): boolean {
    const perms = localPerms[role] || [];
    const wildcard = perms.find((p) => p.resource === "*" && p.action === action);
    if (wildcard) return wildcard.allowed;
    const entry = perms.find((p) => p.resource === resource && p.action === action);
    return entry?.allowed ?? false;
  }

  function toggle(resource: string, action: string) {
    const current = isAllowed(activeRole, resource, action);
    setLocalPerms((prev) => {
      const rolePerms = [...(prev[activeRole] || [])];
      const idx = rolePerms.findIndex(
        (p) => p.resource === resource && p.action === action
      );
      if (idx >= 0) {
        rolePerms[idx] = { ...rolePerms[idx], allowed: !current };
      } else {
        rolePerms.push({ resource, action, allowed: !current });
      }
      return { ...prev, [activeRole]: rolePerms };
    });
  }

  async function save() {
    setSaving(true);
    setMessage("");
    const original = permissions[activeRole] || [];
    const current = localPerms[activeRole] || [];
    const changes: { resource: string; action: string; allowed: boolean }[] = [];

    for (const c of current) {
      const orig = original.find(
        (o) => o.resource === c.resource && o.action === c.action
      );
      if (!orig || orig.allowed !== c.allowed) {
        changes.push(c);
      }
    }

    if (changes.length > 0) {
      await fetch("/api/permissions", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ role: activeRole, changes }),
      });
      setMessage("권한이 저장되었습니다.");
    } else {
      setMessage("변경사항이 없습니다.");
    }
    setSaving(false);
  }

  async function addRole() {
    if (!newRole.trim()) return;
    await fetch("/api/roles", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ role: newRole.trim() }),
    });
    window.location.reload();
  }

  // 역할 탭 순서: ADMIN → DEAN → VIP → 나머지
  const sortedRoles = [...roles].sort((a, b) => {
    const order: Record<string, number> = { ADMIN: 0, DEAN: 1, VIP: 2 };
    return (order[a] ?? 3) - (order[b] ?? 3);
  });

  return (
    <div>
      {/* Header */}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 20, flexWrap: "wrap", gap: 12 }}>
        <div>
          <h2 style={{ fontSize: 18, fontWeight: 600, color: "var(--text-title)", margin: 0 }}>
            권한 관리
          </h2>
          <p style={{ fontSize: 12, color: "var(--text-secondary)", margin: "2px 0 0" }}>
            역할별 페이지 및 기능 접근 권한을 설정합니다
          </p>
        </div>
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
          <div style={{ display: "flex", gap: 4 }}>
            <input
              value={newRole}
              onChange={(e) => setNewRole(e.target.value)}
              placeholder="새 역할명"
              className="input"
              style={{ width: 120 }}
            />
            <button className="btn-secondary" onClick={addRole}>
              + 추가
            </button>
          </div>
          <button className="btn-primary" onClick={save} disabled={saving}>
            {saving ? "저장 중..." : "변경사항 저장"}
          </button>
        </div>
      </div>

      {/* Role tabs */}
      <div style={{ display: "flex", gap: 4, marginBottom: 20 }}>
        {sortedRoles.map((role) => (
          <button
            key={role}
            onClick={() => setActiveRole(role)}
            style={{
              padding: "8px 16px",
              background: role === activeRole ? "var(--deep-green)" : "var(--card-bg)",
              color: role === activeRole ? "#fff" : "var(--text-body)",
              border: role === activeRole ? "none" : "1px solid var(--divider)",
              borderRadius: 6,
              fontSize: 12,
              fontWeight: role === activeRole ? 500 : 400,
              cursor: "pointer",
            }}
          >
            {role}
          </button>
        ))}
      </div>

      {/* Matrix table */}
      <div className="card" style={{ padding: 0, overflow: "hidden" }}>
        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12 }}>
          <thead>
            <tr style={{ background: "var(--header-bg)" }}>
              <th style={{ textAlign: "left", padding: "10px 14px", color: "var(--text-secondary)", fontWeight: 500, fontSize: 11, width: "30%" }}>
                리소스
              </th>
              {ACTIONS.map((a) => (
