import { redirect } from "next/navigation";
import { requireUser, listUsers } from "@/lib/auth";
import { getDepartmentOptions } from "@/lib/queries";
import { checkPermission, getAllRoles, getPermissionsForRole } from "@/lib/permissions";
import AccountPage from "@/components/account-page";

export default async function AccountManagementPage() {
  const user = await requireUser();

  // VIP/ADMIN이 아닌 역할은 이 페이지 접근 불가
  const canViewUsers = checkPermission(user.role, "system.users", "view");
  if (!canViewUsers) {
    redirect("/");
  }

  const users = listUsers();
  const departments = getDepartmentOptions();
  const canViewPermissions = checkPermission(user.role, "system.permissions", "view");

  let roles: string[] = [];
  let permissions: Record<string, { resource: string; action: string; allowed: boolean }[]> = {};

  if (canViewPermissions) {
    roles = getAllRoles();
    for (const role of roles) {
      permissions[role] = getPermissionsForRole(role);
    }
  }

  return (
    <AccountPage
      currentRole={user.role}
      users={users}
      departments={departments}
      roles={roles}
      permissions={permissions}
      canViewPermissions={canViewPermissions}
    />
  );
}

"use client";

import { useState } from "react";
import { useRouter, useSearchParams } from "next/navigation";

export function LoginForm() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setLoading(true);
    setError("");

    try {
      const response = await fetch("/api/auth/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ username, password }),
      });

      if (!response.ok) {
        const data = (await response.json()) as { message?: string };
        throw new Error(data.message ?? "로그인에 실패했습니다.");
      }

      router.push(searchParams.get("next") ?? "/");
      router.refresh();
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "로그인에 실패했습니다.");
    } finally {
      setLoading(false);
    }
  }

  return (
    <form onSubmit={handleSubmit} className="space-y-5">
      <label className="block space-y-2">
        <span style={{ fontSize: 13, fontWeight: 500, color: "var(--text-body)" }}>아이디</span>
        <input
          value={username}
          onChange={(event) => setUsername(event.target.value)}
          className="input"
          style={{ width: "100%", padding: "10px 14px", fontSize: 13, borderRadius: 8 }}
          placeholder="username"
          autoComplete="username"
        />
      </label>
      <label className="block space-y-2">
        <span style={{ fontSize: 13, fontWeight: 500, color: "var(--text-body)" }}>비밀번호</span>
        <input
          type="password"
          value={password}
          onChange={(event) => setPassword(event.target.value)}
          className="input"
          style={{ width: "100%", padding: "10px 14px", fontSize: 13, borderRadius: 8 }}
          placeholder="password"
          autoComplete="current-password"
        />
      </label>

      {error ? (
        <p style={{
          background: "#fdeaea",
          color: "#c0392b",
          padding: "10px 14px",
          borderRadius: 8,
          fontSize: 13,
        }}>
          {error}
        </p>
      ) : null}

      <button
        type="submit"
        disabled={loading}
        style={{
          width: "100%",
          padding: "11px 14px",
          background: "#0a1f14",
          color: "#fff",
          border: "none",
          borderRadius: 8,
          fontSize: 14,
          fontWeight: 600,
          cursor: loading ? "not-allowed" : "pointer",
          opacity: loading ? 0.7 : 1,
        }}
      >
        {loading ? "로그인 중..." : "로그인"}
      </button>
    </form>
  );
}

