"use client";

import type { ProcedureStepRecord } from "@/lib/types";

type ProcedureStepperProps = {
  steps: ProcedureStepRecord[];
  currentStepKey: string;
};

export function ProcedureStepper({
  steps,
  currentStepKey,
}: ProcedureStepperProps) {
  const activeIndex = Math.max(
    steps.findIndex((step) => step.stepKey === currentStepKey),
    0,
  );

  return (
    <ol className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">
      {steps.map((step, index) => {
        const state =
          index < activeIndex
            ? "done"
            : index === activeIndex
              ? "active"
              : "todo";

        return (
          <li
            key={step.stepKey}
            className="card"
            style={{
              border:
                state === "active"
                  ? "1px solid var(--primary-green)"
                  : state === "done"
                    ? "1px solid var(--divider)"
                    : "1px solid var(--divider)",
              background:
                state === "active"
                  ? "var(--card-bg)"
                  : state === "done"
                    ? "var(--row-hover)"
                    : "var(--card-bg)",
              boxShadow: state === "active" ? "0 2px 8px rgba(26,107,74,0.08)" : "none",
              padding: 16,
              borderRadius: 10,
            }}
          >
            <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
              <div
                style={{
                  width: 32,
                  height: 32,
                  borderRadius: "50%",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  fontSize: 12,
                  fontWeight: 700,
                  background:
                    state === "active"
                      ? "var(--gold)"
                      : state === "done"
                        ? "var(--primary-green)"
                        : "var(--divider)",
                  color:
                    state === "active"
                      ? "#111"
                      : state === "done"
                        ? "#fff"
                        : "var(--text-secondary)",
                }}
              >
                {index + 1}
              </div>
              <div>
                <p style={{ fontSize: 10, fontWeight: 500, letterSpacing: "0.12em", textTransform: "uppercase", color: "var(--text-secondary)", margin: 0 }}>
                  Step {index + 1}
                </p>
                <h4 style={{ fontSize: 13, fontWeight: 600, color: "var(--text-title)", margin: 0 }}>
                  {step.stepTitle}
                </h4>
              </div>
            </div>
            <p style={{ marginTop: 10, fontSize: 12, lineHeight: 1.6, color: "var(--text-secondary)" }}>
              {step.stepDescription}
            </p>
          </li>
        );
      })}
    </ol>
  );
}

