import clsx from "clsx";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { Download, ExternalLink, LoaderCircle, Upload } from "lucide-react";
import { ProcedureStepper } from "@/components/procedure-stepper";
import type { AuthUser, WorkflowRequestDetail } from "@/lib/types";

type ProcedureDetailShellProps = {
  detail: WorkflowRequestDetail;
  currentUser: AuthUser;
};

function getInitialDrafts(detail: WorkflowRequestDetail) {
  const drafts: Record<string, Record<string, string>> = {};
  for (const step of detail.steps) {
    drafts[step.stepKey] = { ...(detail.stepPayloads[step.stepKey]?.values ?? {}) };
  }
  return drafts;
}

export function ProcedureDetailShell({ detail, currentUser }: ProcedureDetailShellProps) {
  const router = useRouter();
  const [selectedStepKey, setSelectedStepKey] = useState(detail.request.status);
  const [drafts, setDrafts] = useState<Record<string, Record<string, string>>>(() => getInitialDrafts(detail));
  const [savingStep, setSavingStep] = useState("");
  const [uploading, setUploading] = useState(false);
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");
  const [candidateName, setCandidateName] = useState("");
  const [candidateNotes, setCandidateNotes] = useState("");
  const [candidateFile, setCandidateFile] = useState<File | null>(null);

  const activeStep = useMemo(
    () => detail.steps.find((step) => step.stepKey === selectedStepKey) ?? detail.steps[0],
    [detail.steps, selectedStepKey],
  );
  const activeForm = activeStep ? detail.stepForms[activeStep.stepKey] : null;
  const activePayload = activeStep ? drafts[activeStep.stepKey] ?? {} : {};
  const isAdmin = currentUser.role === "VIP" || currentUser.role === "ADMIN";
  const isCurrentDeanStep =
    currentUser.role === "DEAN" && activeStep?.stepKey === detail.request.status;
  const canEditStep = isAdmin || isCurrentDeanStep;
  const canUpload = isAdmin || currentUser.role === "DEAN";

  function updateField(fieldName: string, value: string) {
    setDrafts((current) => ({
      ...current,
      [selectedStepKey]: {
        ...(current[selectedStepKey] ?? {}),
        [fieldName]: value,
      },
    }));
  }

  async function handleAdminSave(stepKey: string) {
    setSavingStep(stepKey);
    setError("");
    setMessage("");

    const response = await fetch("/api/admin/workflow/step", {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        requestId: detail.request.id,
        stepKey,
        values: drafts[stepKey] ?? {},
      }),
    });

    const data = (await response.json().catch(() => ({}))) as { message?: string };
    if (!response.ok) {
      setError(data.message ?? "단계 입력값 저장에 실패했습니다.");
      setSavingStep("");
      return;
    }

    setMessage("단계 입력값을 저장했습니다.");
    setSavingStep("");
    router.refresh();
  }

  async function handleDeanSubmit(stepKey: string) {
    setSavingStep(stepKey);
    setError("");
    setMessage("");

    const response = await fetch(`/api/recruitment-requests/${detail.request.id}/submit`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        values: drafts[stepKey] ?? {},
      }),
    });

    const data = (await response.json().catch(() => ({}))) as { message?: string };
    if (!response.ok) {
      setError(data.message ?? "현재 단계 제출에 실패했습니다.");
      setSavingStep("");
      return;
    }

    setMessage("현재 단계 입력을 저장하고 다음 단계로 반영했습니다.");
    setSavingStep("");
    router.refresh();
  }

  async function handleCandidateUpload(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!candidateName || !candidateFile) {
      setError("후보자명과 PDF 파일을 입력해야 합니다.");
      return;
    }

    setUploading(true);
    setError("");
    setMessage("");

    const formData = new FormData();
    formData.set("candidateName", candidateName);
    formData.set("notes", candidateNotes);
    formData.set("file", candidateFile);

    const response = await fetch(`/api/recruitment-requests/${detail.request.id}/candidates`, {
      method: "POST",
      body: formData,
    });
    const data = (await response.json().catch(() => ({}))) as { message?: string };
    if (!response.ok) {
      setError(data.message ?? "후보자 데이터 업로드에 실패했습니다.");
      setUploading(false);
      return;
    }

    setCandidateName("");
    setCandidateNotes("");
    setCandidateFile(null);
    setMessage("후보자 데이터를 등록했습니다.");
    setUploading(false);
    router.refresh();
  }

  return (
    <div className="mx-auto max-w-7xl space-y-6">
      {/* Header card */}
      <section className="card">
        <p style={{ fontSize: 10, fontWeight: 600, textTransform: "uppercase", letterSpacing: "0.2em", color: "var(--text-secondary)" }}>Procedure Detail</p>
        <h1 style={{ marginTop: 8, fontSize: 24, fontWeight: 700, color: "var(--text-title)" }}>{detail.request.fieldName}</h1>
        <p style={{ marginTop: 8, color: "var(--text-secondary)", fontSize: 13 }}>
          {detail.department?.college} &middot; {detail.department?.deptName} &middot; {detail.request.hiringType}
        </p>
        <p style={{
          marginTop: 16,
          background: "#fef6e6",
          color: "#8a6d1b",
          padding: "12px 16px",
          borderRadius: 8,
          fontSize: 13,
          lineHeight: 1.7,
        }}>
          현재 필요 조치사항: {detail.request.nextAction ?? "안내 문구가 아직 없습니다."}
        </p>
      </section>

      {/* Stepper */}
      <section className="card">
        <ProcedureStepper steps={detail.steps} currentStepKey={detail.request.status} />
      </section>

      {/* Main content grid */}
      <section className="grid gap-6 xl:grid-cols-[1.15fr_0.85fr]">
        <div className="space-y-6">
          <div className="card">
            <div style={{ display: "flex", flexWrap: "wrap", justifyContent: "space-between", gap: 12, alignItems: "flex-start" }}>
              <div>
                <h2 style={{ fontSize: 16, fontWeight: 600, color: "var(--text-title)", margin: 0 }}>초빙분야별 타임라인 입력값</h2>
                <p style={{ marginTop: 6, fontSize: 12, color: "var(--text-secondary)", lineHeight: 1.6 }}>
                  STEP을 눌러 단계별 입력값을 확인할 수 있습니다. 학과장은 현재 단계에서 바로 입력 후 제출하고,
                  관리자는 모든 단계를 직접 수정할 수 있습니다.
                </p>
              </div>
              <div className="badge badge-progress">
                현재 단계: {activeStep?.stepTitle}
              </div>
            </div>

            {/* Step buttons */}
            <div style={{ marginTop: 16, display: "flex", flexWrap: "wrap", gap: 8 }}>
              {detail.steps.map((step, index) => (
                <button
                  key={step.stepKey}
                  type="button"
                  onClick={() => setSelectedStepKey(step.stepKey)}
                  style={{
                    padding: "8px 14px",
                    borderRadius: 6,
                    fontSize: 12,
                    border: step.stepKey === selectedStepKey ? "none" : "1px solid var(--divider)",
                    background: step.stepKey === selectedStepKey ? "var(--deep-green)" : "var(--card-bg)",
                    color: step.stepKey === selectedStepKey ? "#fff" : "var(--text-body)",
                    cursor: "pointer",
                  }}
                >
                  {`STEP${index + 1}`} {step.stepTitle}
                </button>
              ))}
            </div>

            {/* Active step form */}
            <div className="card" style={{ marginTop: 16, background: "var(--row-hover)", border: "1px solid var(--divider)" }}>
              <h3 style={{ fontSize: 15, fontWeight: 600, color: "var(--text-title)", margin: 0 }}>{activeStep?.stepTitle}</h3>
              <p style={{ marginTop: 6, fontSize: 12, color: "var(--text-secondary)", lineHeight: 1.7 }}>
                {activeForm?.description ?? activeStep?.stepDescription ?? "해당 단계 설명이 아직 없습니다."}
              </p>
              <p style={{ marginTop: 8, fontSize: 11, color: "var(--text-disabled)" }}>
                마지막 저장: {detail.stepPayloads[selectedStepKey]?.createdAt ?? "저장 이력 없음"}
              </p>

              <div style={{ marginTop: 16, display: "grid", gap: 16 }}>
                {activeForm?.fields.length ? (
                  activeForm.fields.map((field) => (
                    <label key={field.name} style={{ display: "block" }}>
                      <span style={{ fontSize: 13, fontWeight: 500, color: "var(--text-body)", display: "block", marginBottom: 6 }}>
                        {field.label}
                        {field.required ? " *" : ""}
                      </span>
                      {field.type === "textarea" ? (
                        <textarea
                          rows={5}
                          value={activePayload[field.name] ?? ""}
                          onChange={(event) => updateField(field.name, event.target.value)}
                          readOnly={!canEditStep}
                          className="input"
                          style={{ width: "100%", lineHeight: 1.6, opacity: canEditStep ? 1 : 0.7 }}
                        />
                      ) : field.type === "select" ? (
                        <select
                          value={activePayload[field.name] ?? ""}
                          onChange={(event) => updateField(field.name, event.target.value)}
                          disabled={!canEditStep}
                          className="input"
                          style={{ width: "100%", opacity: canEditStep ? 1 : 0.7 }}
                        >
                          <option value="">선택하세요</option>
                          {(field.options ?? []).map((option) => (
                            <option key={option} value={option}>
                              {option}
                            </option>
                          ))}
                        </select>
                      ) : (
                        <input
                          type={field.type === "date" ? "text" : field.type}
                          value={activePayload[field.name] ?? ""}
                          onChange={(event) => updateField(field.name, event.target.value)}
                          placeholder={field.type === "date" ? "YYYY-MM-DD" : field.placeholder ?? ""}
                          readOnly={!canEditStep}
                          className="input"
                          style={{ width: "100%", opacity: canEditStep ? 1 : 0.7 }}
                        />
                      )}
                    </label>
                  ))
                ) : (
                  <p style={{ fontSize: 13, color: "var(--text-secondary)" }}>이 단계에는 별도 입력 필드가 없습니다.</p>
                )}
              </div>

              {/* Action buttons */}
              <div style={{ marginTop: 16, display: "flex", flexWrap: "wrap", gap: 10 }}>
                {isAdmin ? (
                  <button
                    type="button"
                    onClick={() => handleAdminSave(selectedStepKey)}
                    disabled={savingStep === selectedStepKey}
                    className="btn-primary"
                    style={{ display: "inline-flex", alignItems: "center", gap: 6 }}
                  >
                    {savingStep === selectedStepKey ? <LoaderCircle className="h-4 w-4 animate-spin" /> : null}
                    단계 입력값 저장
                  </button>
                ) : null}
                {isCurrentDeanStep ? (
                  <button
                    type="button"
                    onClick={() => handleDeanSubmit(selectedStepKey)}
                    disabled={savingStep === selectedStepKey}
                    className="btn-primary"
                    style={{ display: "inline-flex", alignItems: "center", gap: 6 }}
                  >
                    {savingStep === selectedStepKey ? <LoaderCircle className="h-4 w-4 animate-spin" /> : null}
                    현재 단계 저장 및 제출
                  </button>
                ) : null}
                {!isAdmin && !isCurrentDeanStep ? (
                  <p style={{ fontSize: 13, color: "var(--text-secondary)", background: "var(--header-bg)", padding: "10px 16px", borderRadius: 8 }}>
                    학과장은 현재 단계에서만 입력할 수 있습니다.
                  </p>
                ) : null}
              </div>
            </div>
          </div>
        </div>

        {/* Right sidebar */}
        <aside className="space-y-6">
          <section className="card">
            <div style={{ display: "flex", justifyContent: "space-between", gap: 12, alignItems: "flex-start", flexWrap: "wrap" }}>
              <div>
                <h2 style={{ fontSize: 16, fontWeight: 600, color: "var(--text-title)", margin: 0 }}>후보자 입력</h2>
                <p style={{ marginTop: 6, fontSize: 12, color: "var(--text-secondary)", lineHeight: 1.6 }}>
                  후보자 CV와 검증 메모를 초빙분야 기준으로 관리합니다.
                </p>
              </div>
              <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
                <Link href="/candidates" className="btn-secondary" style={{ textDecoration: "none", display: "inline-block" }}>
                  후보자 입력
                </Link>
                <button
                  type="button"
                  onClick={() => window.location.assign("/api/candidates/export")}
                  className="btn-secondary"
                  style={{ display: "inline-flex", alignItems: "center", gap: 6 }}
                >
                  <Download className="h-4 w-4" />
                  전체 다운로드
                </button>
              </div>
            </div>

            <div style={{ marginTop: 16 }} className="space-y-3">
              {detail.candidateProfiles.length ? (
                detail.candidateProfiles.map((candidate) => (
                  <div key={candidate.id} className="card" style={{ background: "var(--row-hover)", border: "1px solid var(--divider)", padding: 14 }}>
                    <div style={{ display: "flex", justifyContent: "space-between", gap: 10, alignItems: "flex-start" }}>
                      <div>
                        <p style={{ fontWeight: 600, color: "var(--text-title)", margin: 0 }}>{candidate.candidateName}</p>
                        <p style={{ marginTop: 4, fontSize: 11, color: "var(--text-disabled)" }}>{candidate.sourceFileName}</p>
                        <p style={{ marginTop: 6, fontSize: 13, color: "var(--text-secondary)" }}>{candidate.notes ?? "메모 없음"}</p>
                      </div>
                      <a
                        href={candidate.publicUrl}
                        target="_blank"
                        rel="noreferrer"
                        className="btn-secondary"
                        style={{ textDecoration: "none", display: "inline-flex", alignItems: "center", gap: 4, fontSize: 11, padding: "4px 10px" }}
                      >
                        열기
                        <ExternalLink className="h-3.5 w-3.5" />
                      </a>
                    </div>
                  </div>
                ))
              ) : (
                <p style={{ fontSize: 13, color: "var(--text-secondary)" }}>아직 등록된 후보자 자료가 없습니다.</p>
              )}
            </div>

            {canUpload ? (
              <form onSubmit={handleCandidateUpload} className="card" style={{ marginTop: 16, background: "var(--row-hover)", border: "1px solid var(--divider)" }}>
                <h3 style={{ fontSize: 14, fontWeight: 600, color: "var(--text-title)", margin: "0 0 12px" }}>후보자 CV 업로드</h3>
                <div className="space-y-3">
                  <input
                    value={candidateName}
                    onChange={(event) => setCandidateName(event.target.value)}
                    placeholder="후보자명"
                    className="input"
                    style={{ width: "100%" }}
                  />
                  <textarea
                    rows={4}
                    value={candidateNotes}
                    onChange={(event) => setCandidateNotes(event.target.value)}
                    placeholder="후보자 메모 또는 검증 코멘트"
                    className="input"
                    style={{ width: "100%", lineHeight: 1.6 }}
                  />
                  <input
                    type="file"
                    accept=".pdf"
                    onChange={(event) => setCandidateFile(event.target.files?.[0] ?? null)}
                    style={{ display: "block", width: "100%", fontSize: 13, color: "var(--text-body)" }}
                  />
                  <button
                    type="submit"
                    disabled={uploading}
                    className="btn-primary"
                    style={{ display: "inline-flex", alignItems: "center", gap: 6 }}
                  >
                    {uploading ? <LoaderCircle className="h-4 w-4 animate-spin" /> : <Upload className="h-4 w-4" />}
                    후보자 자료 저장
                  </button>
                </div>
              </form>
            ) : null}
          </section>

          <section className="card">
            <h2 style={{ fontSize: 16, fontWeight: 600, color: "var(--text-title)", margin: 0 }}>제출 이력</h2>
            <div style={{ marginTop: 12 }} className="space-y-3">
              {detail.submissions.length ? (
                detail.submissions.map((submission) => (
                  <div key={submission.id} className="card" style={{ background: "var(--row-hover)", border: "1px solid var(--divider)", padding: 12 }}>
                    <p style={{ fontSize: 10, fontWeight: 500, textTransform: "uppercase", letterSpacing: "0.15em", color: "var(--text-secondary)", margin: 0 }}>
                      {submission.stepKey} &middot; {submission.createdAt}
                    </p>
                    <p style={{ marginTop: 6, fontSize: 13, color: "var(--text-body)" }}>
                      {submission.statusBefore}
                      {submission.statusAfter ? ` -> ${submission.statusAfter}` : ""}
                    </p>
                  </div>
                ))
              ) : (
                <p style={{ fontSize: 13, color: "var(--text-secondary)" }}>아직 제출 이력이 없습니다.</p>
              )}
            </div>
          </section>

          {message ? (
            <p style={{ background: "var(--light-green)", color: "var(--status-complete)", padding: "10px 16px", borderRadius: 8, fontSize: 13 }}>
              {message}
            </p>
          ) : null}
          {error ? (
            <p style={{ background: "#fdeaea", color: "#c0392b", padding: "10px 16px", borderRadius: 8, fontSize: 13 }}>
              {error}
            </p>
          ) : null}
        </aside>
      </section>
    </div>
  );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import type { WorkflowRequestDetail } from "@/lib/types";

type WorkflowFormProps = {
  detail: WorkflowRequestDetail;
};

export function WorkflowForm({ detail }: WorkflowFormProps) {
  const router = useRouter();
  const [values, setValues] = useState<Record<string, string>>({});
  const [error, setError] = useState("");
  const [saving, setSaving] = useState(false);

  if (!detail.currentForm) {
    return <p style={{ fontSize: 13, color: "var(--text-secondary)" }}>현재 단계에는 제출해야 할 별도 입력 폼이 없습니다.</p>;
  }

  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setSaving(true);
    setError("");

    try {
      const response = await fetch(`/api/recruitment-requests/${detail.request.id}/submit`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ values }),
      });

      if (!response.ok) {
        const data = (await response.json()) as { message?: string };
        throw new Error(data.message ?? "제출에 실패했습니다.");
      }

      router.push(`/procedures/${detail.request.id}`);
      router.refresh();
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "제출에 실패했습니다.");
    } finally {
      setSaving(false);
    }
  }

  return (
    <form onSubmit={handleSubmit} className="space-y-5">
      {detail.currentForm.fields.map((field) => (
        <label key={field.name} style={{ display: "block", marginBottom: 16 }}>
          <span style={{ fontSize: 13, fontWeight: 500, color: "var(--text-body)", display: "block", marginBottom: 6 }}>
            {field.label}
            {field.required ? " *" : ""}
          </span>
          {field.type === "textarea" ? (
            <textarea
              rows={5}
              value={values[field.name] ?? ""}
              onChange={(event) => setValues((current) => ({ ...current, [field.name]: event.target.value }))}
              placeholder={field.placeholder}
              className="input"
              style={{ width: "100%", lineHeight: 1.6 }}
            />
          ) : (
            <input
              type={field.type}
              value={values[field.name] ?? ""}
              onChange={(event) => setValues((current) => ({ ...current, [field.name]: event.target.value }))}
              placeholder={field.placeholder}
              className="input"
              style={{ width: "100%" }}
            />
          )}
          {field.helpText ? <span style={{ fontSize: 11, color: "var(--text-disabled)", display: "block", marginTop: 4 }}>{field.helpText}</span> : null}
        </label>
      ))}

      {error ? (
        <p style={{ background: "#fdeaea", color: "#c0392b", padding: "10px 16px", borderRadius: 8, fontSize: 13 }}>
          {error}
        </p>
      ) : null}

      <button
        type="submit"
        disabled={saving}
        className="btn-primary"
        style={{ opacity: saving ? 0.7 : 1 }}
      >
        {saving ? "제출 중..." : "제출 후 다음 단계로 이동"}
      </button>
    </form>
  );
}

"use client";

import { useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import { FilePlus2, LoaderCircle, PlusSquare, UploadCloud } from "lucide-react";
import type { RecruitmentRequestOption } from "@/lib/types";

type RollingRequestFormProps = {
  deptCode: string;
  requestOptions: RecruitmentRequestOption[];
};

export function RollingRequestForm({ deptCode, requestOptions }: RollingRequestFormProps) {
  const router = useRouter();
  const [fieldName, setFieldName] = useState("");
  const [candidateName, setCandidateName] = useState("");
  const [candidateNotes, setCandidateNotes] = useState("");
  const [hiringReason, setHiringReason] = useState("");
  const [kriFieldName, setKriFieldName] = useState("");
  const [deptRequestReason, setDeptRequestReason] = useState("");
  const [notes, setNotes] = useState("");
  const [file, setFile] = useState<File | null>(null);
  const [submitting, setSubmitting] = useState(false);
  const [message, setMessage] = useState("");

  const selectedRequest = useMemo(() => {
    const normalized = fieldName.trim();
    return requestOptions.find((item) => item.fieldName === normalized) ?? null;
  }, [fieldName, requestOptions]);

  const isExistingField = Boolean(selectedRequest);

  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!fieldName.trim() || !candidateName.trim() || !file) {
      setMessage("초빙분야, 후보자명, 후보자 CV 파일 업로드는 필수입니다.");
      return;
    }

    setSubmitting(true);
    setMessage("");

    const formData = new FormData();
    formData.set("deptCode", deptCode);
    if (selectedRequest) {
      formData.set("existingRequestId", String(selectedRequest.requestId));
    } else {
      formData.set("fieldName", fieldName.trim());
      formData.set("hiringReason", hiringReason);
      formData.set("kriFieldName", kriFieldName);
      formData.set("deptRequestReason", deptRequestReason);
      formData.set("notes", notes);
    }
    formData.set("candidateName", candidateName.trim());
    formData.set("candidateNotes", candidateNotes);
    formData.set("file", file);

    const response = await fetch("/api/recruitment-requests/rolling", {
      method: "POST",
      body: formData,
    });
    const data = (await response.json().catch(() => ({}))) as { message?: string; requestId?: number };
    if (!response.ok) {
      setMessage(data.message ?? "후보자 등록에 실패했습니다.");
      setSubmitting(false);
      return;
    }

    router.push(`/procedures/${data.requestId}`);
    router.refresh();
  }

  return (
    <section className="card">
      <div className="space-y-3">
