"use client";

import { useState } from "react";
import type { UserRecord, UserRole } from "@/lib/types";

type UserAdminPanelProps = {
  initialUsers: UserRecord[];
  departments: Array<{ deptCode: string; deptName: string }>;
};

const ROLES: UserRole[] = ["VIP", "ADMIN", "DEAN"];

export function UserAdminPanel({ initialUsers, departments }: UserAdminPanelProps) {
  const [users, setUsers] = useState(initialUsers);
  const [form, setForm] = useState({
    username: "",
    password: "",
    role: "DEAN" as UserRole,
    departmentCode: departments[0]?.deptCode ?? "",
  });
  const [message, setMessage] = useState("");

  async function refreshUsers() {
    const response = await fetch("/api/users");
    const data = (await response.json()) as { users: UserRecord[] };
    setUsers(data.users);
  }

  async function handleCreate(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const response = await fetch("/api/users", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(form),
    });
    const data = (await response.json()) as { message?: string };
    if (!response.ok) {
      setMessage(data.message ?? "사용자 생성에 실패했습니다.");
      return;
    }
    setMessage("사용자를 생성했습니다.");
    setForm({
      username: "",
      password: "",
      role: "DEAN",
      departmentCode: departments[0]?.deptCode ?? "",
    });
    await refreshUsers();
  }

  async function handleRoleChange(user: UserRecord, role: UserRole) {
    await fetch(`/api/users/${user.id}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ role, departmentCode: role === "DEAN" ? user.departmentCode : null }),
    });
    await refreshUsers();
  }

  return (
    <section>
      <div>
        <h2 style={{ fontSize: 18, fontWeight: 600, color: "var(--text-title)", margin: 0 }}>사용자 관리</h2>
        <p style={{ fontSize: 12, color: "var(--text-secondary)", marginTop: 4 }}>VIP만 사용자 계정과 역할을 관리할 수 있습니다.</p>
      </div>

      <div className="mt-6 grid gap-6 xl:grid-cols-[0.9fr_1.1fr]">
        {/* Create form */}
        <form onSubmit={handleCreate} className="card space-y-4" style={{ background: "var(--row-hover)", border: "1px solid var(--divider)" }}>
          <h3 style={{ fontSize: 14, fontWeight: 600, color: "var(--text-title)", margin: 0 }}>사용자 추가</h3>
          <input
            value={form.username}
            onChange={(event) => setForm((current) => ({ ...current, username: event.target.value }))}
            placeholder="username"
            className="input"
            style={{ width: "100%" }}
          />
          <input
            value={form.password}
            onChange={(event) => setForm((current) => ({ ...current, password: event.target.value }))}
            placeholder="temporary password"
            className="input"
            style={{ width: "100%" }}
          />
          <select
            value={form.role}
            onChange={(event) => setForm((current) => ({ ...current, role: event.target.value as UserRole }))}
            className="input"
            style={{ width: "100%" }}
          >
            {ROLES.map((role) => (
              <option key={role} value={role}>
                {role}
              </option>
            ))}
          </select>
          <select
            value={form.departmentCode}
            onChange={(event) => setForm((current) => ({ ...current, departmentCode: event.target.value }))}
            className="input"
            style={{ width: "100%" }}
          >
            {departments.map((department) => (
              <option key={department.deptCode} value={department.deptCode}>
                {department.deptName}
              </option>
            ))}
          </select>
          <button className="btn-primary">계정 생성</button>
          {message ? <p style={{ fontSize: 13, color: "var(--primary-green)" }}>{message}</p> : null}
        </form>

        {/* User list */}
        <div className="card" style={{ background: "var(--row-hover)", border: "1px solid var(--divider)" }}>
          <h3 style={{ fontSize: 14, fontWeight: 600, color: "var(--text-title)", margin: 0 }}>사용자 목록</h3>
          <div style={{ marginTop: 12 }} className="space-y-3">
            {users.map((user) => (
              <div
                key={user.id}
                className="card"
                style={{
                  display: "flex",
                  flexWrap: "wrap",
                  gap: 12,
                  alignItems: "center",
                  justifyContent: "space-between",
                  padding: "12px 16px",
                  background: "var(--card-bg)",
                  border: "1px solid var(--divider)",
                }}
              >
                <div>
                  <p style={{ fontSize: 13, fontWeight: 600, color: "var(--text-title)", margin: 0 }}>{user.username}</p>
                  <p style={{ marginTop: 4, fontSize: 11, color: "var(--text-secondary)" }}>
                    {user.role}
                    {user.departmentCode ? ` \u00B7 ${user.departmentCode}` : ""}
                  </p>
                </div>
                <select
                  value={user.role}
                  onChange={(event) => handleRoleChange(user, event.target.value as UserRole)}
                  className="input"
                  style={{ fontSize: 11, padding: "4px 10px" }}
                >
                  {ROLES.map((role) => (
                    <option key={role} value={role}>
                      {role}
                    </option>
                  ))}
                </select>
              </div>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}

import Link from "next/link";
import { ArrowLeft } from "lucide-react";
import { requireRole } from "@/lib/auth";
import { canSubmitWorkflow, getRecruitmentRequestDetail } from "@/lib/queries";
import { ProcedureStepper } from "@/components/procedure-stepper";
import { WorkflowForm } from "@/components/workflow-form";

type ActionPageProps = {
  params: Promise<{ requestId: string }>;
};

export default async function ActionPage({ params }: ActionPageProps) {
  const currentUser = await requireRole(["VIP", "DEAN"]);
  const { requestId } = await params;
  const detail = getRecruitmentRequestDetail(Number(requestId), currentUser);

  if (!detail || !canSubmitWorkflow(currentUser, detail.request.deptCode)) {
    return (
      <div style={{ padding: 24, color: "var(--text-body)" }}>
        접근 권한이 없습니다.
      </div>
    );
  }

  return (
    <div className="mx-auto max-w-6xl space-y-6">
      <Link href="/" className="btn-secondary" style={{ textDecoration: "none", display: "inline-flex", alignItems: "center", gap: 6 }}>
        <ArrowLeft className="h-4 w-4" />
        대시보드로 돌아가기
      </Link>

      <section className="card">
        <p style={{ fontSize: 10, fontWeight: 600, textTransform: "uppercase", letterSpacing: "0.2em", color: "var(--text-secondary)" }}>Dean Workflow</p>
        <h1 style={{ marginTop: 8, fontSize: 22, fontWeight: 700, color: "var(--text-title)" }}>{detail.request.fieldName}</h1>
        <p style={{ marginTop: 8, color: "var(--text-secondary)", fontSize: 13 }}>
          {detail.department?.college} &middot; {detail.department?.deptName} &middot; {detail.request.hiringType}
        </p>
        <p style={{
          marginTop: 16,
          background: "#fef6e6",
          color: "#8a6d1b",
          padding: "12px 16px",
          borderRadius: 8,
          fontSize: 13,
          lineHeight: 1.7,
        }}>
          현재 단계에 필요한 데이터를 제출해야만 다음 단계로 이동합니다.
        </p>
      </section>

      <section className="card">
        <ProcedureStepper steps={detail.steps} currentStepKey={detail.request.status} />
      </section>

      <section className="grid gap-6 lg:grid-cols-[1.05fr_0.95fr]">
        <div className="card">
          <h2 style={{ fontSize: 16, fontWeight: 600, color: "var(--text-title)", margin: 0 }}>단계별 필수 입력</h2>
          <p style={{ marginTop: 6, fontSize: 12, color: "var(--text-secondary)" }}>
            {detail.currentForm?.description ?? "제출 폼이 없는 단계입니다."}
          </p>
          <div style={{ marginTop: 16 }}>
            <WorkflowForm detail={detail} />
          </div>
        </div>

        <aside className="card">
          <h2 style={{ fontSize: 16, fontWeight: 600, color: "var(--text-title)", margin: 0 }}>제출 이력</h2>
          <div style={{ marginTop: 12 }} className="space-y-3">
            {detail.submissions.length ? (
              detail.submissions.map((submission) => (
                <div key={submission.id} className="card" style={{ background: "var(--row-hover)", border: "1px solid var(--divider)", padding: 12 }}>
                  <p style={{ fontSize: 10, fontWeight: 500, textTransform: "uppercase", letterSpacing: "0.15em", color: "var(--text-secondary)", margin: 0 }}>
                    {submission.stepKey} &middot; {submission.createdAt}
                  </p>
                  <p style={{ marginTop: 6, fontSize: 13, color: "var(--text-body)" }}>
                    {submission.statusBefore}
                    {submission.statusAfter ? ` -> ${submission.statusAfter}` : ""}
                  </p>
                </div>
              ))
            ) : (
              <p style={{ fontSize: 13, color: "var(--text-secondary)" }}>아직 제출 이력이 없습니다.</p>
            )}
          </div>
        </aside>
      </section>
    </div>
  );
}

